{
  "name": "opencode-openai-sub-switcher",
  "version": "1.0.7",
  "description": "Multi-account OpenAI authentication plugin for OpenCode. Supports multiple ChatGPT Plus/Pro accounts with easy switching.",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./cli": {
      "import": "./dist/cli.js",
      "types": "./dist/cli.d.ts"
    }
  },
  "bin": {
    "opencode-openai-sub-switcher": "bin/cli.js",
    "opencode-openai-sub-switcher-install": "scripts/install-opencode.mjs",
    "opencode-openai-sub-switcher-uninstall": "scripts/uninstall-opencode.mjs"
  },
  "files": [
    "dist",
    "bin",
    "README.md",
    "LICENSE",
    "scripts"
  ],
  "scripts": {
    "build": "tsc",
    "install:opencode": "node ./scripts/install-opencode.mjs",
    "uninstall:opencode": "node ./scripts/uninstall-opencode.mjs"
  },
  "keywords": [
    "opencode",
    "plugin",
    "openai",
    "auth",
    "multi-account",
    "codex"
  ],
  "author": "davecodes",
  "license": "MIT",
  "dependencies": {
    "@opencode-ai/plugin": "^1.4.0",
    "@opencode-ai/sdk": "^1.4.0",
    "effect": "^3.10.0"
  },
  "devDependencies": {
    "typescript": "^5.4.0",
    "@types/node": "^20.0.0"
  },
  "peerDependencies": {}
}

#!/usr/bin/env node
import { runCli } from "../dist/cli.js"

runCli(process.argv.slice(2)).catch((err) => {
  console.error(err)
  process.exit(1)
})

import { captureCurrentAccount, formatAccountForDisplay, getCurrentIdentityKey, listAccounts as loadAccounts, removeAccountById as deleteAccountById, renameAccount, restoreAccountById, } from "./auth.js";
export async function runCli(args) {
    const command = args[0];
    switch (command) {
        case "list":
            printAccounts();
            break;
        case "add":
            addAccount(args[1]);
            break;
        case "remove":
            if (!args[1]) {
                console.error("Usage: opencode-openai-sub-switcher remove <id>");
                process.exit(1);
            }
            deleteAccountById(args[1]);
            break;
        case "rename":
            if (!args[1] || !args[2]) {
                console.error("Usage: opencode-openai-sub-switcher rename <id> <label>");
                process.exit(1);
            }
            renameAccountCli(args[1], args.slice(2).join(" "));
            break;
        case "switch":
            if (!args[1]) {
                console.error("Usage: opencode-openai-sub-switcher switch <id>");
                process.exit(1);
            }
            switchAccount(args[1]);
            break;
        default:
            console.log(`Usage: opencode-openai-sub-switcher <command>

Commands:
  list                List all saved accounts
  add [label]         Save the current OpenCode OpenAI auth
  switch <id>         Restore an account into ~/.local/share/opencode/auth.json
  remove <id>         Remove an account
  rename <id> <label> Rename an account
`);
    }
}
function printAccounts() {
    const accounts = loadAccounts();
    const currentIdentityKey = getCurrentIdentityKey();
    if (accounts.length === 0) {
        console.log("No accounts saved. Log in with OpenCode OpenAI, then run `opencode-openai-sub-switcher add` or `/switch-sub`.");
        return;
    }
    console.log("Saved OpenAI accounts:");
    console.log("");
    for (const account of accounts) {
        console.log(formatAccountForDisplay(account, currentIdentityKey === account.identityKey));
    }
}
function addAccount(label) {
    const account = captureCurrentAccount(label);
    if (!account) {
        console.error("No current OpenCode OpenAI auth found.");
        process.exit(1);
    }
    console.log(`Saved account: ${formatAccountForDisplay(account).trim()}`);
}
function removeAccountById(id) {
    const ok = deleteAccountById(id);
    if (ok) {
        console.log("Account removed.");
    }
    else {
        console.error("Account not found.");
        process.exit(1);
    }
}
function renameAccountCli(id, label) {
    const ok = renameAccount(id, label);
    if (!ok) {
        console.error("Account not found.");
        process.exit(1);
    }
    console.log("Account renamed.");
}
function switchAccount(id) {
    const restored = restoreAccountById(id);
    if (!restored) {
        console.error("Account not found.");
        process.exit(1);
    }
    console.log(`Switched to ${formatAccountForDisplay({
        id,
        label: restored.label,
        email: restored.email,
        planType: restored.planType,
        accountId: restored.accountId,
    }).trim()}.`);
}
