import { tool } from "@opencode-ai/plugin";
import { captureCurrentAccount, findAccountDisplayById, formatAccountForDisplay, getCurrentIdentityKey, listAccounts, removeAccountById, renameAccount, restoreAccountById, } from "./auth.js";
export const server = async (ctx) => {
    return {
        tool: {
            list_openai_accounts: tool({
                description: "List all saved OpenAI accounts in the multi-account registry.",
                args: {},
                async execute() {
                    const accounts = listAccounts();
                    if (accounts.length === 0) {
                        return "No saved accounts. Log in with OpenCode OpenAI, then run `save_current_openai_account`.";
                    }
                    const currentIdentityKey = getCurrentIdentityKey();
                    const lines = accounts.map((a) => formatAccountForDisplay(a, currentIdentityKey === a.identityKey));
                    return "Saved OpenAI accounts:\n\n" + lines.join("\n");
                },
            }),
            switch_openai_account: tool({
                description: "Switch to a saved OpenCode OpenAI auth snapshot by ID.",
                args: {
                    id: tool.schema.string().describe("Account ID from list_openai_accounts"),
                },
                async execute(args) {
                    const snapshot = restoreAccountById(args.id);
                    if (!snapshot) {
                        return { output: `Account ${args.id} not found.` };
                    }
                    await ctx.client.auth.set({
                        path: { id: "openai" },
                        body: {
                            type: "oauth",
                            access: snapshot.oauth.access,
                            refresh: snapshot.oauth.refresh,
                            expires: snapshot.oauth.expires,
                        },
                    });
                    const saved = findAccountDisplayById(args.id);
                    return { output: `Switched to ${saved ? formatAccountForDisplay(saved).trim() : "selected account"}.` };
                },
            }),
            remove_openai_account: tool({
                description: "Remove a saved OpenAI account from the registry.",
                args: {
                    id: tool.schema.string().describe("Account ID from list_openai_accounts"),
                },
                async execute(args) {
                    const ok = removeAccountById(args.id);
                    return { output: ok ? "Account removed." : `Account ${args.id} not found.` };
                },
            }),
            rename_openai_account: tool({
                description: "Rename a saved OpenAI account.",
                args: {
                    id: tool.schema.string().describe("Account ID from list_openai_accounts"),
                    label: tool.schema.string().describe("New label for the account"),
                },
                async execute(args) {
                    const ok = renameAccount(args.id, args.label);
                    return { output: ok ? "Account renamed." : `Account ${args.id} not found.` };
                },
            }),
            save_current_openai_account: tool({
                description: "Save the currently active OpenCode OpenAI auth snapshot to the multi-account registry.",
                args: {
                    label: tool.schema.string().optional().describe("Optional custom label for this account"),
                },
                async execute(args) {
                    const account = captureCurrentAccount(args.label);
                    if (!account) {
                        return { output: "No OpenCode OAuth auth found. Log in with OpenCode/OpenAI first." };
                    }
                    return { output: `Saved account ${formatAccountForDisplay(account).trim()}.` };
                },
            }),
        },
    };
};
export default server;
